INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1929749, 263857, 37893, '<td valign="top">Good photo but you left text within the photo which might be construed as a violation of the rules. Good luck.</td>', 'Good photo but you left text within the photo which might be construed as a violation of the rules. Good luck.', '2005-12-07 00:26:32.000000', NULL, 1),
(1929751, 265764, 37893, '<td valign="top">This image is way to small. WOuld have been a great one and fits the challenge perfectly.</td>', 'This image is way to small. WOuld have been a great one and fits the challenge perfectly.', '2005-12-07 00:27:18.000000', NULL, 1),
(1929775, 266136, 42714, '<td valign="top">Good concept, enjoy the photo.  Two recommendations.  Lost of focus on the first row of seats, would consider cropping just above the "desks" of the first row.  Secondly, is the top of the photography.  The black sliver of ceiling showing up on the right hand side, combined with the askew vertical lines are distracting.  Rotating your photo with some more acute cropping could really increase the quality of your photo.</td>', 'Good concept, enjoy the photo.  Two recommendations.  Lost of focus on the first row of seats, would consider cropping just above the "desks" of the first row.  Secondly, is the top of the photography.  The black sliver of ceiling showing up on the right hand side, combined with the askew vertical lines are distracting.  Rotating your photo with some more acute cropping could really increase the quality of your photo.', '2005-12-07 00:33:04.000000', NULL, 1),
(1929793, 265884, 15711, '<td valign="top">This has kind of a 60''s snapshot sense with the blueness to the skin tones.  I don''t know if it is on purpose or not.  On one level, I kinda like it.  Then on another... not so sure. The subjects are clear yet have a certain softness to them.</td>', 'This has kind of a 60''s snapshot sense with the blueness to the skin tones.  I don''t know if it is on purpose or not.  On one level, I kinda like it.  Then on another... not so sure. The subjects are clear yet have a certain softness to them.', '2005-12-07 00:37:52.000000', NULL, 1),
(1929801, 266174, 15711, '<td valign="top">Spooky and forboding. I like the hint of light here and there.  Nice perspective.</td>', 'Spooky and forboding. I like the hint of light here and there.  Nice perspective.', '2005-12-07 00:39:30.000000', NULL, 1),
(1929808, 266117, 15711, '<td valign="top">HO HO HO - Great idea. Love his expression.  So cute.  Would make an adorable greeting card.  The humor of it is fun to view.  Nice perspective. Perfect for the challenge. 8</td>', 'HO HO HO - Great idea. Love his expression.  So cute.  Would make an adorable greeting card.  The humor of it is fun to view.  Nice perspective. Perfect for the challenge. 8', '2005-12-07 00:40:59.000000', NULL, 1),
(1929820, 266136, 15711, '<td valign="top">WOW the intense colors and sharpness is amazing.  Great leading line with all of the rows of the chairs. His blue shirt mimics the tone of the wall.  I''d work on his skin tones and make them yes yellow, or maybe you wanted his arms to match the gold of the chair arms. Still - a vivid eye catching image. Nice job.</td>', 'WOW the intense colors and sharpness is amazing.  Great leading line with all of the rows of the chairs. His blue shirt mimics the tone of the wall.  I''d work on his skin tones and make them yes yellow, or maybe you wanted his arms to match the gold of the chair arms. Still - a vivid eye catching image. Nice job.', '2005-12-07 00:43:10.000000', NULL, 1),
(1929827, 263885, 15711, '<td valign="top">Really a cool portrait. I love the lighting and his fade to black body.  Nicely done.  Kinda creepy.</td>', 'Really a cool portrait. I love the lighting and his fade to black body.  Nicely done.  Kinda creepy.', '2005-12-07 00:44:18.000000', NULL, 1),
(1929836, 266177, 15711, '<td valign="top">ROFL.  Such a fun imaginative take on the challenge.  I like this alot.  Nicely detailed. I''d like maybe a touch more negative space so he''s not so center, but this is really clever. 8</td>', 'ROFL.  Such a fun imaginative take on the challenge.  I like this alot.  Nicely detailed. I''d like maybe a touch more negative space so he''s not so center, but this is really clever. 8', '2005-12-07 00:46:20.000000', NULL, 1),
(1929841, 264953, 42826, '<td valign="top">what a beautiful cock...hahaha, bright and colorful!!!  what are those spots in the background...:)</td>', 'what a beautiful cock...hahaha, bright and colorful!!!  what are those spots in the background...:)', '2005-12-07 00:47:39.000000', NULL, 1),
(1929845, 265122, 15711, '<td valign="top">LOVE THIS!!! Great filter.  The reflection is wonderful and so clear. Almost like a mirror. Nicely composed.</td>', 'LOVE THIS!!! Great filter.  The reflection is wonderful and so clear. Almost like a mirror. Nicely composed.', '2005-12-07 00:48:01.000000', NULL, 1),
(1929847, 266162, 42714, '<td valign="top">As a baseball fan, I really like this.  I saw another one like this, but this is much better executed.  Great lighting and setup.</td>', 'As a baseball fan, I really like this.  I saw another one like this, but this is much better executed.  Great lighting and setup.', '2005-12-07 00:48:06.000000', NULL, 1),
(1929850, 265496, 15711, '<td valign="top">Nicely composed.  This is really cool. Interesting and artsy!!</td>', 'Nicely composed.  This is really cool. Interesting and artsy!!', '2005-12-07 00:48:44.000000', NULL, 1),
(1929851, 266177, 42826, '<td valign="top">don''t put the other end in your mouth</td>', 'don''t put the other end in your mouth', '2005-12-07 00:48:48.000000', NULL, 1),
(1929855, 265485, 15711, '<td valign="top">In a word: WOW<br/> <br/>Stunning vibrant tones and I love the subject being so far from the front of the shot.  Nice and very artfully created.</td>', 'In a word: WOW Stunning vibrant tones and I love the subject being so far from the front of the shot.  Nice and very artfully created.', '2005-12-07 00:49:28.000000', NULL, 1),
(1929860, 264853, 48717, '<td valign="top">I have not looked at the rest of the entries, but this may very well be my number 1.  Perfect everything.</td>', 'I have not looked at the rest of the entries, but this may very well be my number 1.  Perfect everything.', '2005-12-07 00:50:28.000000', NULL, 1),
(1929864, 265244, 15711, '<td valign="top">Love this.  I have a theory that bananas are only perfect to eat in about a 3 second window. ha ha ha  Nicely done. Love the color and unusual take on the challenge.</td>', 'Love this.  I have a theory that bananas are only perfect to eat in about a 3 second window. ha ha ha  Nicely done. Love the color and unusual take on the challenge.', '2005-12-07 00:51:04.000000', NULL, 1),
(1929912, 265821, 42714, '<td valign="top">I love simplicity in photography and you nailed it here.</td>', 'I love simplicity in photography and you nailed it here.', '2005-12-07 01:06:04.000000', NULL, 1),
(1929927, 265704, 15711, '<td valign="top">WOw - this is cool and very nostalgic for me.</td>', 'WOw - this is cool and very nostalgic for me.', '2005-12-07 01:10:11.000000', NULL, 1),
(1929940, 265788, 45926, '<td valign="top">Wow, really interesting photograph! The colors are really neat. But the numbers look sort of fuzzy?</td>', 'Wow, really interesting photograph! The colors are really neat. But the numbers look sort of fuzzy?', '2005-12-07 01:13:39.000000', NULL, 1),
(1929947, 265015, 45926, '<td valign="top">Excellent clarity!! Great shot!</td>', 'Excellent clarity!! Great shot!', '2005-12-07 01:15:25.000000', NULL, 1),
(1929953, 265497, 43809, '<td valign="top">think it would have fit the too late contest better???</td>', 'think it would have fit the too late contest better???', '2005-12-07 01:18:07.000000', NULL, 1),
(1929959, 266144, 45926, '<td valign="top">Ugh.. I dislike parents who think that they should stuff their child''s mind with nonsense that they can barely understand at an early age. Nice colors, perhaps more lighting on the top right corner though?</td>', 'Ugh.. I dislike parents who think that they should stuff their child''s mind with nonsense that they can barely understand at an early age. Nice colors, perhaps more lighting on the top right corner though?', '2005-12-07 01:21:15.000000', NULL, 1),
(1929968, 265621, 45926, '<td valign="top">When I saw the thumbnail of this, I was amazed! I really like the clarity, and colors in the picture. The expression on her face is really strange, it''s like the mona lisa or something! I can''t tell if she''s sad, or pretending to be happy even though she''s sad.. or something like that. The reasons above are the reasons that i simply adore this picture.</td>', 'When I saw the thumbnail of this, I was amazed! I really like the clarity, and colors in the picture. The expression on her face is really strange, it''s like the mona lisa or something! I can''t tell if she''s sad, or pretending to be happy even though she''s sad.. or something like that. The reasons above are the reasons that i simply adore this picture.', '2005-12-07 01:24:00.000000', NULL, 1),
(1929986, 265821, 15711, '<td valign="top">Wonderful DOF.  I like the bokeh effect.  Beautiful clarity to the flower. WOW Stunning.</td>', 'Wonderful DOF.  I like the bokeh effect.  Beautiful clarity to the flower. WOW Stunning.', '2005-12-07 01:29:53.000000', NULL, 1),
(1929988, 266041, 43809, '<td valign="top">would have created a lot more impact if taken at a macro level to make the curves near the contact visible</td>', 'would have created a lot more impact if taken at a macro level to make the curves near the contact visible', '2005-12-07 01:30:17.000000', NULL, 1),
(1930009, 263857, 43809, '<td valign="top">i guess ur pic is going to be DQed...nice shot though</td>', 'i guess ur pic is going to be DQed...nice shot though', '2005-12-07 01:34:55.000000', NULL, 1),
(1930011, 263885, 35545, '<td valign="top">Nice portrait, but what has this to do with Too Early?</td>', 'Nice portrait, but what has this to do with Too Early?', '2005-12-07 01:35:03.000000', NULL, 1),
(1930015, 265298, 16241, '<td valign="top">nice, simple, colourful, effective</td>', 'nice, simple, colourful, effective', '2005-12-07 01:36:23.000000', NULL, 1),
(1930018, 265533, 16241, '<td valign="top">very nice!</td>', 'very nice!', '2005-12-07 01:36:59.000000', NULL, 1),
(1930032, 265521, 43772, '<td valign="top">too neat imaged? doesnt look real although interesting</td>', 'too neat imaged? doesnt look real although interesting', '2005-12-07 01:40:08.000000', NULL, 1),
(1930039, 264716, 5885, '<td valign="top">I like the idea of the shot, but it has a few problems. Tilted horizon is a big problem for me, that could be easily fixed in a graphics program. Composition could be stronger, perhaps moving the model to the other side of the bed and not having hte matress showing on the opposite side of her could have strengthened it.<br/> <br/>Your background failed to go completely black on the black portions. That would have helped the shot some.<br/> <br/>I''m going to give you an 8 though. Nudes in non-nude challenges don''t tend to do really well around here, so I wish you the best of luck.</td>', 'I like the idea of the shot, but it has a few problems. Tilted horizon is a big problem for me, that could be easily fixed in a graphics program. Composition could be stronger, perhaps moving the model to the other side of the bed and not having hte matress showing on the opposite side of her could have strengthened it. Your background failed to go completely black on the black portions. That would have helped the shot some. I''m going to give you an 8 though. Nudes in non-nude challenges don''t tend to do really well around here, so I wish you the best of luck.', '2005-12-07 01:41:24.000000', NULL, 1),
(1930072, 264734, 45961, '<td valign="top">Oh she''s so adorable! I''m sorry I gave a 3 though. I''ll explain why. The picture is a better grainy and quite our of focus. There''s a bit of the red eye effect as well. The title doesn''t work for the shot as well. To me the title says the mum went in to take the shot, but it looks more like the little girl came out to show mum. There is too much shine on her dress as well.<br/>My mum loves the shot of this girl though. Great effort.</td>', 'Oh she''s so adorable! I''m sorry I gave a 3 though. I''ll explain why. The picture is a better grainy and quite our of focus. There''s a bit of the red eye effect as well. The title doesn''t work for the shot as well. To me the title says the mum went in to take the shot, but it looks more like the little girl came out to show mum. There is too much shine on her dress as well.My mum loves the shot of this girl though. Great effort.', '2005-12-07 01:52:55.000000', NULL, 1),
(1930081, 265928, 45961, '<td valign="top">This show isn''t working for me at all. I''m could be really dumb not understanding the whole picture to fit the challenge. Evolution it may be, but I don''t see transformation. So I gave a 3 on this. It''s a bit grainy, but I do like the surreal effect done on it.</td>', 'This show isn''t working for me at all. I''m could be really dumb not understanding the whole picture to fit the challenge. Evolution it may be, but I don''t see transformation. So I gave a 3 on this. It''s a bit grainy, but I do like the surreal effect done on it.', '2005-12-07 01:55:49.000000', NULL, 1),
(1930090, 265895, 45961, '<td valign="top">I think you''ve over saturated the red. I gave a 4 on this because it fits the theme. It''s a good picture, but there is too much noise. I think it''s also over sharpened as well. It might have worked a bit better if placed in a better looking background.</td>', 'I think you''ve over saturated the red. I gave a 4 on this because it fits the theme. It''s a good picture, but there is too much noise. I think it''s also over sharpened as well. It might have worked a bit better if placed in a better looking background.', '2005-12-07 01:57:56.000000', NULL, 1),
(1930091, 264778, 48717, '<td valign="top">Great pic, would love to see it in color.</td>', 'Great pic, would love to see it in color.', '2005-12-07 01:58:13.000000', NULL, 1),
(1930106, 265664, 45961, '<td valign="top">Oh dear it''s very grainy. I like the concept. I gave it a 4 for having the concept link to the theme. Perhaps if you could do a clearer shot without including the entire line up. I personally think by having so many people in this particular shot, it  distracts the attention from the main focal point.</td>', 'Oh dear it''s very grainy. I like the concept. I gave it a 4 for having the concept link to the theme. Perhaps if you could do a clearer shot without including the entire line up. I personally think by having so many people in this particular shot, it  distracts the attention from the main focal point.', '2005-12-07 02:01:40.000000', NULL, 1),
(1930116, 265298, 45961, '<td valign="top">The shot is quite out of focus and there''s too much sharpening going on. Maybe the wall was too high? I''m not sure, but the composition isn''t great. I gave it a 4. It''s a good shot though. Oh and the contrast works quite well.</td>', 'The shot is quite out of focus and there''s too much sharpening going on. Maybe the wall was too high? I''m not sure, but the composition isn''t great. I gave it a 4. It''s a good shot though. Oh and the contrast works quite well.', '2005-12-07 02:03:24.000000', NULL, 1),
(1930118, 263885, 48717, '<td valign="top">Great pic, but...huh?  I think this is lost in translation for me.  Google could not help me either :-(</td>', 'Great pic, but...huh?  I think this is lost in translation for me.  Google could not help me either :-(', '2005-12-07 02:03:48.000000', NULL, 1),
(1930126, 263885, 45961, '<td valign="top">Beautiful shot, I like it very much. I originally gave this a 4, but I''m changing to a 5. Although there''s one thing missing, I don''t see how it fits the challenge. I would have given it a higher score though if it weren''t for the missing link.</td>', 'Beautiful shot, I like it very much. I originally gave this a 4, but I''m changing to a 5. Although there''s one thing missing, I don''t see how it fits the challenge. I would have given it a higher score though if it weren''t for the missing link.', '2005-12-07 02:05:09.000000', NULL, 1),
(1930132, 266075, 45961, '<td valign="top">It''s too grainy. I like the concept going on, but it''s not captured very well. If this were taken in a more contrasting sky compared to the building I would have rated this a bit higher. The focus isn''t all that great. So I gave this a 4.</td>', 'It''s too grainy. I like the concept going on, but it''s not captured very well. If this were taken in a more contrasting sky compared to the building I would have rated this a bit higher. The focus isn''t all that great. So I gave this a 4.', '2005-12-07 02:06:40.000000', NULL, 1),
(1930142, 265204, 45961, '<td valign="top">Bliss it may be, the crackling of leaves under your feet. This shot isn''t working very well. So I gave it a 4. The angle is lovely, but it''s rather small, and I''m almost certain a lot of comments will be saying the same. I feel like there is no focal point on this picture. The lack of contrast.</td>', 'Bliss it may be, the crackling of leaves under your feet. This shot isn''t working very well. So I gave it a 4. The angle is lovely, but it''s rather small, and I''m almost certain a lot of comments will be saying the same. I feel like there is no focal point on this picture. The lack of contrast.', '2005-12-07 02:08:53.000000', NULL, 1),
(1930150, 265496, 45961, '<td valign="top">Unique framing you''ve done. Very much like the triptych strategy. I just don''t understand the picture very well. The contrast works fairly well with the break of dawn. I''m thinking a railroad crossing and a truck went past. So I gave a 5 for this.</td>', 'Unique framing you''ve done. Very much like the triptych strategy. I just don''t understand the picture very well. The contrast works fairly well with the break of dawn. I''m thinking a railroad crossing and a truck went past. So I gave a 5 for this.', '2005-12-07 02:12:01.000000', NULL, 1),
(1930157, 265829, 45961, '<td valign="top">You''ve got the challenge right on, but the focal point isn''t so great. The picture itself is boring to me. I don''t mean to offend you or anything, I''m just attracted to pictures with a lot of contrast. This doesn''t have much. I like the way you''ve shown the whole place seems to be empty though. I have a 4.</td>', 'You''ve got the challenge right on, but the focal point isn''t so great. The picture itself is boring to me. I don''t mean to offend you or anything, I''m just attracted to pictures with a lot of contrast. This doesn''t have much. I like the way you''ve shown the whole place seems to be empty though. I have a 4.', '2005-12-07 02:13:35.000000', NULL, 1),
(1930165, 264967, 45961, '<td valign="top">Honestly, I don''t understand the picture. I know it says "Feb1st" as the opening date, but I''m not sure if a too late or early. The picture doesn''t have that extra "umph" in it. It could be because it was too cloudy. Something in the composition doesn''t work very well is what I''m trying to say. So for that I gave a 4.</td>', 'Honestly, I don''t understand the picture. I know it says "Feb1st" as the opening date, but I''m not sure if a too late or early. The picture doesn''t have that extra "umph" in it. It could be because it was too cloudy. Something in the composition doesn''t work very well is what I''m trying to say. So for that I gave a 4.', '2005-12-07 02:15:30.000000', NULL, 1),
(1930169, 265866, 45961, '<td valign="top">I had to give this one a 4. A very plain shot. The black and white works well, but there is no real subject. I read the title to give me a bit more understanding to the picture, but it doesn''t make real sense to me. But maybe this picture was taken at dawn, so I thought it would fit the challenge. I gave that score because it probably fits the challenge.</td>', 'I had to give this one a 4. A very plain shot. The black and white works well, but there is no real subject. I read the title to give me a bit more understanding to the picture, but it doesn''t make real sense to me. But maybe this picture was taken at dawn, so I thought it would fit the challenge. I gave that score because it probably fits the challenge.', '2005-12-07 02:17:38.000000', NULL, 1),
(1930180, 266136, 46341, '<td valign="top">Excellent capture.</td>', 'Excellent capture.', '2005-12-07 02:20:15.000000', NULL, 1),
(1930181, 265841, 45961, '<td valign="top">The shot is rather blurry, so I had to take off points there. It''s also quite small. I do like the concept being worked on though. Are you sure it''s napping though? It looks very posed. Plus the part of the head is chopped off! Maybe cropping out the ladies at the corner might work a bit more and giving the guy his head back. For this shot, I gave a 4.</td>', 'The shot is rather blurry, so I had to take off points there. It''s also quite small. I do like the concept being worked on though. Are you sure it''s napping though? It looks very posed. Plus the part of the head is chopped off! Maybe cropping out the ladies at the corner might work a bit more and giving the guy his head back. For this shot, I gave a 4.', '2005-12-07 02:20:44.000000', NULL, 1),
(1930182, 264739, 46601, '<td valign="top">Amazing sky ... too bad about the spots on the right hand corner sort of distracts from the shot</td>', 'Amazing sky ... too bad about the spots on the right hand corner sort of distracts from the shot', '2005-12-07 02:21:11.000000', NULL, 1),
(1930188, 265805, 45961, '<td valign="top">A lot of people have used clocks. The picture itself is small and grainy, so I gave a 4. There isn''t much going on in this shot, in this case it''s not really good. It fits the theme so that score was given. If you could have shown more to the picture, like a grungy person stuck in bed unwilling to come out, might have worked better.</td>', 'A lot of people have used clocks. The picture itself is small and grainy, so I gave a 4. There isn''t much going on in this shot, in this case it''s not really good. It fits the theme so that score was given. If you could have shown more to the picture, like a grungy person stuck in bed unwilling to come out, might have worked better.', '2005-12-07 02:22:41.000000', NULL, 1),
(1930191, 265922, 45961, '<td valign="top">There were quite a few baseball gloves being shot, so this was given a 5 because it lacks the location compared to the others I''ve seen. It would have scored a bit higher if there was some sort of background to show the wait for spring. It''s a good shot though!</td>', 'There were quite a few baseball gloves being shot, so this was given a 5 because it lacks the location compared to the others I''ve seen. It would have scored a bit higher if there was some sort of background to show the wait for spring. It''s a good shot though!', '2005-12-07 02:24:22.000000', NULL, 1),
(1930193, 264708, 35545, '<td valign="top">What''s too early?  It looks like you''re right on time.  Good capture.  I love the water.</td>', 'What''s too early?  It looks like you''re right on time.  Good capture.  I love the water.', '2005-12-07 02:25:04.000000', NULL, 1),
(1930195, 266173, 35545, '<td valign="top">Good idea, but the background looks over-processed.</td>', 'Good idea, but the background looks over-processed.', '2005-12-07 02:25:56.000000', NULL, 1),
(1930199, 265664, 35545, '<td valign="top">Needs to be in focus.</td>', 'Needs to be in focus.', '2005-12-07 02:26:49.000000', NULL, 1),
(1930206, 265607, 49159, '<td valign="top">it looks natural... too early to get up</td>', 'it looks natural... too early to get up', '2005-12-07 02:30:04.000000', NULL, 1),
(1930207, 265568, 35545, '<td valign="top">Really cute pose.  I wish you hadn''t cut off the top of her head.   I just don''t get a feeling of Too Early out of this.</td>', 'Really cute pose.  I wish you hadn''t cut off the top of her head.   I just don''t get a feeling of Too Early out of this.', '2005-12-07 02:30:10.000000', NULL, 1),
(1930211, 265866, 35545, '<td valign="top">Interesting composition, but I don''t see anything to do with Too Early here.</td>', 'Interesting composition, but I don''t see anything to do with Too Early here.', '2005-12-07 02:31:09.000000', NULL, 1),
(1930214, 265838, 35545, '<td valign="top">Nice nice shot, but but what are you too early for?  The picture doesn''t tell me.</td>', 'Nice nice shot, but but what are you too early for?  The picture doesn''t tell me.', '2005-12-07 02:32:54.000000', NULL, 1),
(1930219, 264778, 45961, '<td valign="top">This is an unbelievable shot! That tiger getting attacked squinched even. I hope it''s just playful demeanor. I have this shot a 7 though. I might have given it a 9 or 10 if you could go for a faster shutter speed to have that pause effect on the paws. Using black and while on this works fairly well, the framing works really good in this composition.</td>', 'This is an unbelievable shot! That tiger getting attacked squinched even. I hope it''s just playful demeanor. I have this shot a 7 though. I might have given it a 9 or 10 if you could go for a faster shutter speed to have that pause effect on the paws. Using black and while on this works fairly well, the framing works really good in this composition.', '2005-12-07 02:34:04.000000', NULL, 1),
(1930222, 263857, 35545, '<td valign="top">Nice picture of the girl, but what''s too early about this?</td>', 'Nice picture of the girl, but what''s too early about this?', '2005-12-07 02:35:01.000000', NULL, 1),
(1930226, 263857, 45961, '<td valign="top">I know it will be disqualified because of the text and a bit more, but I just wanted to say, it''s a great shot. The composition compliments the model. I gave this one a 6. Having that glow for the model is great, but then again I don''t see how it fits the challenge despite a great portrait shot.</td>', 'I know it will be disqualified because of the text and a bit more, but I just wanted to say, it''s a great shot. The composition compliments the model. I gave this one a 6. Having that glow for the model is great, but then again I don''t see how it fits the challenge despite a great portrait shot.', '2005-12-07 02:36:03.000000', NULL, 1),
(1930233, 265568, 45961, '<td valign="top">Very creative is the word I can say for this one. The baby is adorable. I think it''s lacking a focal point though. Some areas are a bit too blurry. I do love the concept going for this composition; it''s working very well. Only if the baby had her/his hands around the camera. I''d throw a 10. Instead I gave a 7.</td>', 'Very creative is the word I can say for this one. The baby is adorable. I think it''s lacking a focal point though. Some areas are a bit too blurry. I do love the concept going for this composition; it''s working very well. Only if the baby had her/his hands around the camera. I''d throw a 10. Instead I gave a 7.', '2005-12-07 02:38:43.000000', NULL, 1),
(1930235, 265023, 35545, '<td valign="top">I really, really like this picture, but I can''t figure out what''s too early.</td>', 'I really, really like this picture, but I can''t figure out what''s too early.', '2005-12-07 02:39:37.000000', NULL, 1),
