(1936095, 265885, 33732, '<td valign="top">Interesting. Too early?  Seems like to late.</td>', 'Interesting. Too early?  Seems like to late.', '2005-12-08 17:37:28.000000', NULL, 1),
(1936101, 265771, 33732, '<td valign="top">Nice idea. You don''t seem to get the idea from the photo. More contrast would help make the weather more of a threat.</td>', 'Nice idea. You don''t seem to get the idea from the photo. More contrast would help make the weather more of a threat.', '2005-12-08 17:40:02.000000', NULL, 1),
(1936102, 266144, 33732, '<td valign="top">Very good idea and composition and color.  Good luck.</td>', 'Very good idea and composition and color.  Good luck.', '2005-12-08 17:40:45.000000', NULL, 1),
(1936160, 266102, 44728, '<td valign="top">Hmm u must be british :-)<br/>Nice idea, good photo, maybe the yellow colour on the egs are not well enough.</td>', 'Hmm u must be british :-)Nice idea, good photo, maybe the yellow colour on the egs are not well enough.', '2005-12-08 18:17:05.000000', NULL, 1),
(1936164, 266037, 44728, '<td valign="top">Nice photo, good use of colours too. Maybe a bit lower angle 8</td>', 'Nice photo, good use of colours too. Maybe a bit lower angle 8', '2005-12-08 18:18:53.000000', NULL, 1),
