(1936212, 265830, 43565, '<td valign="top">Good idea, but  I wish it was more in focus.</td>', 'Good idea, but  I wish it was more in focus.', '2005-12-08 18:38:14.000000', NULL, 1),
(1936215, 265841, 43565, '<td valign="top">This looks more like a snapshot.  I think you should have gotten all of him in the shot, with less wall to the right.  Maybe also a different angle.  Also, try to make the largest side 640.</td>', 'This looks more like a snapshot.  I think you should have gotten all of him in the shot, with less wall to the right.  Maybe also a different angle.  Also, try to make the largest side 640.', '2005-12-08 18:40:04.000000', NULL, 1),
(1936216, 265670, 44980, '<td valign="top">This is a striking image. 10</td>', 'This is a striking image. 10', '2005-12-08 18:40:46.000000', NULL, 1),
(1936219, 265838, 43565, '<td valign="top">Not sure how this fits too early--to me it looks more like you were too late to catch the bus.</td>', 'Not sure how this fits too early--to me it looks more like you were too late to catch the bus.', '2005-12-08 18:42:36.000000', NULL, 1),
(1936222, 264716, 43565, '<td valign="top">Not sure what you were too early for...</td>', 'Not sure what you were too early for...', '2005-12-08 18:43:58.000000', NULL, 1),
(1936225, 266174, 43565, '<td valign="top">I like the color (or lack of color).  Definitely feels like winter.  Seems to meet the challenge as well as any I have seen yet.</td>', 'I like the color (or lack of color).  Definitely feels like winter.  Seems to meet the challenge as well as any I have seen yet.', '2005-12-08 18:46:49.000000', NULL, 1),
(1936230, 263885, 43565, '<td valign="top">I like the lighting, but I think it would have worked better with less of his body included.  (I am not sure how this fits the challenge.)</td>', 'I like the lighting, but I think it would have worked better with less of his body included.  (I am not sure how this fits the challenge.)', '2005-12-08 18:49:44.000000', NULL, 1),
(1936233, 265805, 43565, '<td valign="top">I think for this kind of shot, you need to add a creative element--angle, lighting, or something to make it more interesting.  Try to resize so the largest side is 640.</td>', 'I think for this kind of shot, you need to add a creative element--angle, lighting, or something to make it more interesting.  Try to resize so the largest side is 640.', '2005-12-08 18:51:33.000000', NULL, 1),
(1936266, 264697, 42638, '<td valign="top">Beautiful picture, Very simple, sharp and focused. Great color.</td>', 'Beautiful picture, Very simple, sharp and focused. Great color.', '2005-12-08 19:11:29.000000', NULL, 1),
(1936268, 265118, 42638, '<td valign="top">Absolutely love it, I Never get that timer right. Great idea and composition.</td>', 'Absolutely love it, I Never get that timer right. Great idea and composition.', '2005-12-08 19:12:35.000000', NULL, 1),
(1936269, 265613, 42638, '<td valign="top">Nice capture. Love the pose, Good eye!</td>', 'Nice capture. Love the pose, Good eye!', '2005-12-08 19:13:01.000000', NULL, 1),
