INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1936594, 265952, 49297, '<td valign="top">Neat Concept.</td>', 'Neat Concept.', '2005-12-08 21:42:20.000000', NULL, 1),
(1936596, 265885, 49297, '<td valign="top">I would have liked some more color or something in the boat. But I really like the concept and image overall.</td>', 'I would have liked some more color or something in the boat. But I really like the concept and image overall.', '2005-12-08 21:43:32.000000', NULL, 1),
(1936600, 265704, 49297, '<td valign="top">Diggin'' the concept. Not sold completely on the execution. I think the foreground bothers me. Nice job, though.</td>', 'Diggin'' the concept. Not sold completely on the execution. I think the foreground bothers me. Nice job, though.', '2005-12-08 21:45:10.000000', NULL, 1),
(1936604, 265670, 49297, '<td valign="top">Nice! I like the color! Very intense. Nice tension iwth the cracks and the cropping. You get enough of the shape to know it''s an egg...but it''s still ambiguous. Nice.</td>', 'Nice! I like the color! Very intense. Nice tension iwth the cracks and the cropping. You get enough of the shape to know it''s an egg...but it''s still ambiguous. Nice.', '2005-12-08 21:46:16.000000', NULL, 1),
(1936606, 265607, 49297, '<td valign="top">That''s what I call too Early!! Everyone seems to be using the alarm clock idea... finally got the expressin of the person to get the idea across. No caption needed for this piece. I would have liked a more dramatic early morning light with rich shadows, though.</td>', 'That''s what I call too Early!! Everyone seems to be using the alarm clock idea... finally got the expressin of the person to get the idea across. No caption needed for this piece. I would have liked a more dramatic early morning light with rich shadows, though.', '2005-12-08 21:47:41.000000', NULL, 1),
(1936609, 266136, 49297, '<td valign="top">Been there. Nice work with the blue shirt! Works really well to pop out of the red chairs with the blue background!</td>', 'Been there. Nice work with the blue shirt! Works really well to pop out of the red chairs with the blue background!', '2005-12-08 21:48:25.000000', NULL, 1),
(1936611, 265493, 49297, '<td valign="top">Nice photo! But this time of day is just perfect...it''s so peace and quiet... not too early at all!</td>', 'Nice photo! But this time of day is just perfect...it''s so peace and quiet... not too early at all!', '2005-12-08 21:49:38.000000', NULL, 1),
(1936613, 266162, 49297, '<td valign="top">Nice! Great idea. I think the light''s a little intense, though. The ball seems burned out a little.</td>', 'Nice! Great idea. I think the light''s a little intense, though. The ball seems burned out a little.', '2005-12-08 21:50:27.000000', NULL, 1),
(1936616, 265821, 49297, '<td valign="top">Very nice capture. even though the subject is dead center... I like the composition.</td>', 'Very nice capture. even though the subject is dead center... I like the composition.', '2005-12-08 21:51:11.000000', NULL, 1),
(1936617, 266174, 49297, '<td valign="top">Very moody. Not too keen on concept, though.</td>', 'Very moody. Not too keen on concept, though.', '2005-12-08 21:51:41.000000', NULL, 1),
(1936666, 265568, 46468, '<td valign="top">Really LOVE this one, the look on the baby''s face is just such concentration. As if the baby seriously wants to figure out how to use that camera. She is a cutie, but would have to agree that it is a wee bit "too early" for her to start taking pics. LOL Good luck!</td>', 'Really LOVE this one, the look on the baby''s face is just such concentration. As if the baby seriously wants to figure out how to use that camera. She is a cutie, but would have to agree that it is a wee bit "too early" for her to start taking pics. LOL Good luck!', '2005-12-08 22:16:03.000000', NULL, 1),
(1936673, 265464, 46468, '<td valign="top">Well done, love the colors, the composition,  and the clarity.  Good luck!<br/></td>', 'Well done, love the colors, the composition,  and the clarity.  Good luck!', '2005-12-08 22:18:32.000000', NULL, 1),
(1936675, 265621, 46468, '<td valign="top">She really seems to be intent on applying that makeup. Well done</td>', 'She really seems to be intent on applying that makeup. Well done', '2005-12-08 22:19:40.000000', NULL, 1),
(1936678, 266037, 46468, '<td valign="top">Really love the colors and the composition. Only thing I would have prefered would have been less lighting, to really show the "too early" aspect. Like as day breaks type thing. Good Luck</td>', 'Really love the colors and the composition. Only thing I would have prefered would have been less lighting, to really show the "too early" aspect. Like as day breaks type thing. Good Luck', '2005-12-08 22:21:25.000000', NULL, 1),
(1936694, 265952, 46468, '<td valign="top">Like the look of the kernel, esp. with the wetness of the kernel and the oil away from it. Won''t be long before it is popcorn, but you are "too eary" to catch it. The reflection of the photographer is a wee bit distracting and the play of light on the right upper part vs the darkness of the left upper side distracts a wee bit also. Overall a nice macro, good luck.</td>', 'Like the look of the kernel, esp. with the wetness of the kernel and the oil away from it. Won''t be long before it is popcorn, but you are "too eary" to catch it. The reflection of the photographer is a wee bit distracting and the play of light on the right upper part vs the darkness of the left upper side distracts a wee bit also. Overall a nice macro, good luck.', '2005-12-08 22:27:15.000000', NULL, 1),
(1936697, 265118, 46468, '<td valign="top">Yes, the photographer was a bit "too early" and the subject a bit "too late". Love the concept, esp as the photographer and subject are the same but fault of the timing the opposite. Good luck 7</td>', 'Yes, the photographer was a bit "too early" and the subject a bit "too late". Love the concept, esp as the photographer and subject are the same but fault of the timing the opposite. Good luck 7', '2005-12-08 22:30:03.000000', NULL, 1),
(1936712, 265023, 49297, '<td valign="top">Nice idea. Seems static. This would be great if it could look a little more candid. Very nice, though</td>', 'Nice idea. Seems static. This would be great if it could look a little more candid. Very nice, though', '2005-12-08 22:35:42.000000', NULL, 1),
(1936713, 264736, 49297, '<td valign="top">cliche''. Also... light doesn''t seem natural. 4:30 is still dark. Looks articificial.</td>', 'cliche''. Also... light doesn''t seem natural. 4:30 is still dark. Looks articificial.', '2005-12-08 22:36:16.000000', NULL, 1),
(1936716, 265953, 49297, '<td valign="top">great idea. It would be cool if it looked like the person was in mid-jump. Kinda'' looks like a guy just standing there as a ball is thrown over his head.  But I love the idea.</td>', 'great idea. It would be cool if it looked like the person was in mid-jump. Kinda'' looks like a guy just standing there as a ball is thrown over his head.  But I love the idea.', '2005-12-08 22:37:18.000000', NULL, 1),
(1936720, 265256, 49297, '<td valign="top">interesting. Very high contrast... not sure if I like that on this one. Very busy. My eye bounces from figure to the bag in the foreground to the sign he''s holding. Good idea.</td>', 'interesting. Very high contrast... not sure if I like that on this one. Very busy. My eye bounces from figure to the bag in the foreground to the sign he''s holding. Good idea.', '2005-12-08 22:38:12.000000', NULL, 1),
(1936721, 265023, 46468, '<td valign="top">Love the effect of the "magic" sparkles around her, nicely done. The lights on the tree are distracting as the seem to harsh compared to the rest of the picture. Otherwise very nicely done holiday picture. Good luck</td>', 'Love the effect of the "magic" sparkles around her, nicely done. The lights on the tree are distracting as the seem to harsh compared to the rest of the picture. Otherwise very nicely done holiday picture. Good luck', '2005-12-08 22:38:21.000000', NULL, 1),
(1936724, 266102, 49297, '<td valign="top">Hah.  I like. I like the play on color. I think the butter''s color is a bit too intense. Tone down the eggs and butter and brighten up the beer color, perhaps. I like the composition overall. Not sure if I like the 1/2 of a hand, though. Nice job.</td>', 'Hah.  I like. I like the play on color. I think the butter''s color is a bit too intense. Tone down the eggs and butter and brighten up the beer color, perhaps. I like the composition overall. Not sure if I like the 1/2 of a hand, though. Nice job.', '2005-12-08 22:39:57.000000', NULL, 1),
(1936727, 265821, 46468, '<td valign="top">Nicely done, would have worked equally well as "too early" or "too late" Either way that flower does not look like it should be there at this time. Good luck</td>', 'Nicely done, would have worked equally well as "too early" or "too late" Either way that flower does not look like it should be there at this time. Good luck', '2005-12-08 22:40:49.000000', NULL, 1),
(1936728, 265349, 49297, '<td valign="top">Cliche'' but more realistic time/lighting feel. I like the crop. Perhaps even closer in to the clock and the hand. Bring moretension into it? Looks like the hand is just sitting on the clock... posed.</td>', 'Cliche'' but more realistic time/lighting feel. I like the crop. Perhaps even closer in to the clock and the hand. Bring moretension into it? Looks like the hand is just sitting on the clock... posed.', '2005-12-08 22:41:05.000000', NULL, 1),
(1936730, 266075, 49297, '<td valign="top">I''d have liked to see a closer crop on the clock.</td>', 'I''d have liked to see a closer crop on the clock.', '2005-12-08 22:41:58.000000', NULL, 1),
(1936732, 266037, 49297, '<td valign="top">Neat shot. I like the color. The blue foreground boat and the small yellow one in the middle ground is kinda'' nice.</td>', 'Neat shot. I like the color. The blue foreground boat and the small yellow one in the middle ground is kinda'' nice.', '2005-12-08 22:42:46.000000', NULL, 1),
(1936733, 264953, 49297, '<td valign="top">Woop... that''s bright red. I like the close up. Nice detail. I would say the color might be a touch too intense.. but it''s a great image.</td>', 'Woop... that''s bright red. I like the close up. Nice detail. I would say the color might be a touch too intense.. but it''s a great image.', '2005-12-08 22:43:40.000000', NULL, 1),
(1936735, 265747, 46468, '<td valign="top">Really love this pic. That is a beautiful dog. Really seems to be very intent on that stocking, he/she wants here bone now and doesn''t want to wait until Christmas. Hope you gave it to him/her for being such a photogenic dog.  Background, esp with the fire going, works well. Good luck</td>', 'Really love this pic. That is a beautiful dog. Really seems to be very intent on that stocking, he/she wants here bone now and doesn''t want to wait until Christmas. Hope you gave it to him/her for being such a photogenic dog.  Background, esp with the fire going, works well. Good luck', '2005-12-08 22:44:26.000000', NULL, 1),
(1936736, 265020, 49297, '<td valign="top">Nice timing. Diggin'' the muzzle flash! Not too keen on the lighting/composition...but nice idea.</td>', 'Nice timing. Diggin'' the muzzle flash! Not too keen on the lighting/composition...but nice idea.', '2005-12-08 22:45:14.000000', NULL, 1),
(1936738, 265244, 49297, '<td valign="top">Very nice. I like the color. Perhaps more of a crop to make it more tense. Close enough to crop out the brown part of the banana stem?</td>', 'Very nice. I like the color. Perhaps more of a crop to make it more tense. Close enough to crop out the brown part of the banana stem?', '2005-12-08 22:46:11.000000', NULL, 1),
(1936739, 265764, 49297, '<td valign="top">Nice concept.</td>', 'Nice concept.', '2005-12-08 22:46:28.000000', NULL, 1),
(1936740, 264740, 49297, '<td valign="top">I like birds. Seems a little over exposed though.</td>', 'I like birds. Seems a little over exposed though.', '2005-12-08 22:47:03.000000', NULL, 1),
(1936742, 264778, 49297, '<td valign="top">Wow... very neat!</td>', 'Wow... very neat!', '2005-12-08 22:47:19.000000', NULL, 1),
(1936746, 264992, 49297, '<td valign="top">hmm... nice light. Great colors. Pretty neat. I''m dying to see the splash!</td>', 'hmm... nice light. Great colors. Pretty neat. I''m dying to see the splash!', '2005-12-08 22:48:19.000000', NULL, 1),
